#!/usr/bin/env python3
"""Build a focused harness around the real soup_headers_parse_request body.

The function body is extracted verbatim from the supplied target source file
(no reimplementation): we locate the definition by name and brace-match.
Minimal stubs replace glib/soup dependencies that are irrelevant to the
version-parsing path under test.
"""
import re
import sys
from pathlib import Path

STUBS = r'''
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef int gboolean;
typedef unsigned int guint;
typedef unsigned long gulong;
typedef bool SoupMessageHeaders;   /* opaque, unused in the parse path */
typedef int SoupHTTPVersion;

#define TRUE 1
#define FALSE 0
#define NULL_STUB 0

enum {
    SOUP_STATUS_MALFORMED = 400,
    SOUP_STATUS_BAD_REQUEST = 400,
    SOUP_STATUS_OK = 200,
    SOUP_STATUS_HTTP_VERSION_NOT_SUPPORTED = 505,
    SOUP_STATUS_EXPECTATION_FAILED = 417,
};
#define SOUP_EXPECTATION_UNRECOGNIZED (1u << 0)
#define SOUP_HTTP_1_0 0
#define SOUP_HTTP_1_1 1

/* Faithful glib macro semantics: return the fallback value on failure. */
#define g_return_val_if_fail(expr, val) do { if (!(expr)) return (val); } while (0)
#define g_ascii_isdigit(c) ((unsigned char)(c) >= '0' && (unsigned char)(c) <= '9')
#define g_strndup(s, n) strndup((s), (n))

/* Irrelevant-to-the-path dependencies: stubbed so the real body links. */
static gboolean soup_headers_parse_impl (const char *str, int len,
                                         SoupMessageHeaders *dest) {
    (void)str; (void)len; (void)dest; return TRUE;
}
#define soup_headers_parse soup_headers_parse_impl

static guint soup_message_headers_get_expectations_impl (SoupMessageHeaders *h) {
    (void)h; return 0;
}
#define soup_message_headers_get_expectations soup_message_headers_get_expectations_impl

static void soup_message_headers_clean_connection_headers_impl (SoupMessageHeaders *h) {
    (void)h;
}
#define soup_message_headers_clean_connection_headers soup_message_headers_clean_connection_headers_impl
'''

MAIN = r'''
/* Exactly the upstream regression fixture: 15 bytes, no NUL terminator. */
static char unterminated_http_version[] = {
        'G','E','T',' ','/',' ','H','T','T','P','/','1', '0', '0', '.'
};

int main (void) {
    SoupMessageHeaders hdrs;
    char *method = NULL, *path = NULL;
    SoupHTTPVersion ver;
    guint status;

    /* Positive path: a normal valid request must still parse. */
    {
        const char *ok = "GET / HTTP/1.1\r\nHost: example.com\r\n";
        status = soup_headers_parse_request (ok, (int)strlen (ok), &hdrs,
                                             &method, &path, &ver);
        printf ("positive: status=%u method=%s path=%s ver=%d\n",
                status, method ? method : "(null)", path ? path : "(null)", ver);
        free (method); free (path); method = path = NULL;
    }

    /* Negative path: crafted version passes the version+8 sanity check
     * and then would read one byte past the buffer. */
    {
        status = soup_headers_parse_request (unterminated_http_version,
                                             (int)sizeof (unterminated_http_version),
                                             &hdrs, &method, &path, &ver);
        printf ("crafted: status=%u\n", status);
        free (method); free (path);
        if (status != SOUP_STATUS_BAD_REQUEST) {
            printf ("FAIL: crafted request should be BAD_REQUEST\n");
            return 2;
        }
    }
    printf ("RESULT: OK\n");
    return 0;
}
'''


def extract_function(text: str, name: str) -> str:
    # Find definition: a line that ends with the function name and has an open brace.
    sig = re.compile(r"^[A-Za-z_][A-Za-z0-9_ \t\*]*\b" + re.escape(name) + r"\s*\(")
    lines = text.splitlines(keepends=True)
    start = None
    for i, line in enumerate(lines):
        if sig.match(line):
            start = i
            break
    if start is None:
        raise SystemExit(f"function {name} not found")
    # brace-match from first '{'
    depth = 0
    started = False
    out = []
    for line in lines[start:]:
        out.append(line)
        for ch in line:
            if ch == '{':
                depth += 1
                started = True
            elif ch == '}':
                depth -= 1
        if started and depth == 0:
            return ''.join(out)
    raise SystemExit("unbalanced braces")


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: make_harness.py <soup-headers.c> <output.c>", file=sys.stderr)
        return 1
    src = Path(sys.argv[1]).read_text(encoding="utf-8", errors="replace")
    fn = extract_function(src, "soup_headers_parse_request")
    Path(sys.argv[2]).write_text(STUBS + "\n" + fn + "\n" + MAIN, encoding="utf-8")
    print(f"wrote {sys.argv[2]} ({len(fn.splitlines())} function lines)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

